class Cart {private final double[] prices;private final String cartId;Cart(String id,int capacity){cartId=id;prices=new double[capacity];}void addItem(double price){if(price<0)throw new IllegalArgumentException("Price cannot be negative");for(int i=0;i<prices.length;i++)if(prices[i]==0){prices[i]=price;return;}throw new IllegalStateException("Cart is full");}double getTotal(){double total=0;for(double p:prices)total+=p;return total;}int getItemCount(){int count=0;for(double p:prices)if(p!=0)count++;return count;}String getCartId(){return cartId;}}
public class ShoppingCartDemo {public static void main(String[] args){Cart c=new Cart("C-101",10);c.addItem(250);c.addItem(99);c.addItem(151);System.out.println("Total: "+c.getTotal());System.out.println("Count: "+c.getItemCount());}}
